import React from 'react';
import {
  Button,
  LinListToolbar,
  buildCatalogListToolbarActions,
} from '@linm-soft-org/linm-web-common-components';

export type CatalogToolbarParams = {
  testIdPrefix: string;
  onRefresh: () => void;
  canAdd?: boolean;
  onAdd?: () => void;
  createLabel?: string;
  canHistory?: boolean;
  onHistory?: () => void;
  showSchemaConfig?: boolean;
  onEditConfig?: () => void;
  showEdit?: boolean;
  showView?: boolean;
  onEdit?: () => void;
  onView?: () => void;
  canDelete?: boolean;
  onDelete?: () => void;
  selectedCount?: number;
};

/** Kind B catalog toolbar FULL — buildCatalogListToolbarActions (SSOT). */
export function fromCatalogToolbar(tb: CatalogToolbarParams): React.ReactElement {
  return (
    <LinListToolbar
      testIdPrefix={tb.testIdPrefix}
      profile="catalog"
      actions={buildCatalogListToolbarActions({
        testIdPrefix: tb.testIdPrefix,
        canAdd: tb.canAdd,
        onAdd: tb.onAdd,
        createLabel: tb.createLabel,
        onRefresh: tb.onRefresh,
        canHistory: tb.canHistory,
        onHistory: tb.onHistory,
        showSchemaConfig: tb.showSchemaConfig,
        onEditConfig: tb.onEditConfig,
        showEdit: tb.showEdit,
        showView: tb.showView,
        onEdit: tb.onEdit,
        onView: tb.onView,
        canDelete: tb.canDelete,
        onDelete: tb.onDelete,
        selectedCount: tb.selectedCount,
      })}
    />
  );
}

export type RmmsGenericListToolbarParams = {
  testIdPrefix: string;
  onRefresh: () => void;
  onCreate?: () => void;
  canCreate?: boolean;
  createLabel?: string;
};

/** List chrome — minimal generic (Làm mới · Tạo mới). */
export function buildRmmsGenericListToolbar(
  p: RmmsGenericListToolbarParams,
): React.ReactElement {
  return fromCatalogToolbar({
    testIdPrefix: p.testIdPrefix,
    onRefresh: p.onRefresh,
    canAdd: p.canCreate !== false && Boolean(p.onCreate),
    onAdd: p.onCreate,
    createLabel: p.createLabel,
  });
}

export function rmmsFormActionButton(p: {
  testId: string;
  label: string;
  icon: string;
  onClick: () => void;
  variant?: 'primary' | 'secondary';
  loading?: boolean;
}): React.ReactElement {
  return (
    <Button
      variant={p.variant ?? 'secondary'}
      size="md"
      title={p.label}
      onClick={p.onClick}
      loading={p.loading}
      data-testid={p.testId}
      style={{ minWidth: 100 }}
    >
      <i className={p.icon} aria-hidden /> {p.label}
    </Button>
  );
}

export type RmmsDetailToolbarParams = {
  testIdPrefix: string;
  onBack: () => void;
  backLabel?: string;
  right?: React.ReactNode;
};

/** Detail chrome — Quay lại trái · workflow phải · title/badge dưới toolbar. */
export function buildRmmsDetailToolbar(p: RmmsDetailToolbarParams): React.ReactElement {
  return (
    <LinListToolbar
      testIdPrefix={p.testIdPrefix}
      profile="generic"
      actions={[
        {
          id: 'back',
          placement: 'left',
          testId: `${p.testIdPrefix}-back-btn`,
          render: () => (
            <Button
              variant="secondary"
              size="sm"
              data-testid={`${p.testIdPrefix}-back-btn`}
              onClick={p.onBack}
            >
              <i className="fas fa-arrow-left" aria-hidden /> {p.backLabel ?? 'Quay lại'}
            </Button>
          ),
        },
        ...(p.right
          ? [
              {
                id: 'right',
                placement: 'right' as const,
                render: () => <>{p.right}</>,
              },
            ]
          : []),
      ]}
    />
  );
}
