import type { SearchInputConfig } from '@linm-soft-org/linm-web-common-components';
import {
  SEARCH_DROPDOWN_PORTAL,
  catalogLookupColumns,
  catalogLookupHeader,
} from '../../search/searchDropdownDefaults';
import { PATROL_STATUSES, PATROL_TYPES } from '../../demo/patrolStore';
import {
  ROAD_ROUTE_LOOKUP_CONFIG,
  ROAD_ROUTE_SEED,
  lookupLabel as lookupRoadRouteLabel,
  lookupNameOnly,
} from '../attendance/lookups';

export { ROAD_ROUTE_LOOKUP_CONFIG, ROAD_ROUTE_SEED, lookupRoadRouteLabel, lookupNameOnly };

export type MasterLookupItem = {
  value: string;
  label: string;
};

export const STATUS_LOOKUP: MasterLookupItem[] = PATROL_STATUSES.map((value) => ({
  value,
  label: value,
}));

export const TYPE_LOOKUP: MasterLookupItem[] = PATROL_TYPES.map((value) => ({
  value,
  label: value,
}));

export const OFFLINE_LOOKUP: MasterLookupItem[] = [
  { value: 'false', label: 'Online' },
  { value: 'true', label: 'Offline queue' },
];

function searchMaster(
  items: MasterLookupItem[],
  search?: string,
): { items: MasterLookupItem[]; page: number; totalPages: number } {
  const q = (search ?? '').trim().toLowerCase();
  const filtered = q
    ? items.filter(
        (i) =>
          i.value.toLowerCase().includes(q) || i.label.toLowerCase().includes(q),
      )
    : items;
  return { items: filtered, page: 1, totalPages: 1 };
}

export function masterLookupConfig(
  items: MasterLookupItem[],
): SearchInputConfig<MasterLookupItem> {
  return {
    api: {
      getItemKey: (i) => i.value,
      search: async ({ search }) => searchMaster(items, search),
      getDetail: async (id) =>
        items.find((i) => i.value === id) ?? { value: id, label: id },
    },
    display: {
      getPrimaryDisplay: (i) => i.label,
      getSecondaryDisplay: (i) => i.label,
      getSingleDisplay: (i) => i.label,
    },
    ...SEARCH_DROPDOWN_PORTAL,
    columns: catalogLookupColumns(),
    header: catalogLookupHeader(),
    pageSize: 50,
  };
}

export const STATUS_LOOKUP_CONFIG = masterLookupConfig(STATUS_LOOKUP);
export const TYPE_LOOKUP_CONFIG = masterLookupConfig(TYPE_LOOKUP);
export const OFFLINE_LOOKUP_CONFIG = masterLookupConfig(OFFLINE_LOOKUP);

export function lookupLabel(items: MasterLookupItem[], value: string): string {
  return items.find((i) => i.value === value)?.label ?? value;
}
