import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useDispatch } from 'react-redux';
import { useSearchParams } from 'react-router-dom';
import {
  Button,
  DEFAULT_CATALOG_LIST_TABLE_CONFIG,
  ErpListHeaderFilters,
  LinCatalogDataGrid,
  LinCatalogHistoryModal,
  LinCatalogListPagination,
  LinCatalogRowActionMenu,
  LinListFilterField,
  LinPageLayout,
  SearchInput,
  SearchTextInput,
  buildCatalogRowMenuItems,
  dispatchAppToast,
  useCatalogHistoryModal,
  useErpListSelection,
  useServerPagedListLoading,
  type LinCatalogDataColumn,
} from '@linm-soft-org/linm-web-common-components';
import { useInAppNavigate } from '../../router/navigateInAppPath';
import { patrolService } from '../../services/patrol/patrolService';
import { patrolListPermissions } from '../../services/patrol/permissions';
import type { PatrolDto } from '../../services/patrol/responseModel';
import {
  STATUS_LOOKUP,
  STATUS_LOOKUP_CONFIG,
  ROAD_ROUTE_LOOKUP_CONFIG,
  ROAD_ROUTE_SEED,
  lookupLabel,
  lookupNameOnly,
} from '../../services/patrol/lookups';
import styles from './PatrolListPage.module.css';
import { fromCatalogToolbar } from '../buildRmmsGenericToolbar';

const TEST_ID = 'rmms-patrol-list';
const PAGE_ID = 'patrol';
const ROW_MENU_HINT_KEY = `${TEST_ID}-row-menu-hint-dismissed`;

function formatDate(iso: string): string {
  if (!iso) return '—';
  try {
    const d = new Date(iso.length === 10 ? `${iso}T00:00:00` : iso);
    return d.toLocaleDateString('vi-VN');
  } catch {
    return iso;
  }
}

const PatrolListPage: React.FC = () => {
  const dispatch = useDispatch();
  const catalogHistory = useCatalogHistoryModal();
  const navigate = useInAppNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const perms = patrolListPermissions();

  const [searchDraft, setSearchDraft] = useState('');
  const [statusDraft, setStatusDraft] = useState('');
  const [routeDraft, setRouteDraft] = useState('');
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [routeFilter, setRouteFilter] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState<number>(50);
  const [items, setItems] = useState<PatrolDto[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [rowMenu, setRowMenu] = useState<{
    x: number;
    y: number;
    row: PatrolDto;
  } | null>(null);
  const [configHint, setConfigHint] = useState(false);

  const {
    showTableLoading,
    pageLoading,
    pulseSearch,
    setLoadingMode,
    beginFetch,
    endFetch,
  } = useServerPagedListLoading();

  const load = useCallback(() => {
    beginFetch();
    patrolService
      .getList({
        search: search.trim() || undefined,
        status: statusFilter || undefined,
        route: routeFilter || undefined,
        page,
        pageSize,
      })
      .then((res) => {
        setItems(res.items);
        setTotalCount(res.totalCount);
      })
      .catch(() => {
        setItems([]);
        setTotalCount(0);
      })
      .finally(() => endFetch());
  }, [search, statusFilter, routeFilter, page, pageSize, beginFetch, endFetch]);

  useEffect(() => {
    let cancelled = false;
    const t = window.setTimeout(() => {
      if (!cancelled) load();
    }, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, [load]);

  useEffect(() => {
    const form = searchParams.get('form');
    if (!form) return;
    const id = searchParams.get('id');
    if (form === 'create') {
      navigate('/td-tk/tao-moi', { replace: true });
      return;
    }
    if (id && (form === 'edit' || form === 'view' || form === 'copy')) {
      if (form === 'copy') {
        navigate(`/td-tk/tao-moi?copyFrom=${encodeURIComponent(id)}`, { replace: true });
        return;
      }
      const qs = form === 'edit' ? '?mode=edit' : '';
      navigate(`/td-tk/${encodeURIComponent(id)}${qs}`, { replace: true });
      return;
    }
    setSearchParams({}, { replace: true });
  }, [searchParams, setSearchParams, navigate]);

  const listSelection = useErpListSelection<PatrolDto>({
    rows: items,
    totalCount,
    page,
    pageSize,
    getRowId: (r) => r.id,
  });
  const { activeRow, selectActiveRow, clearSelection } = listSelection;

  const applyFilters = useCallback(
    (nextSearch: string, nextStatus: string, nextRoute: string) => {
      pulseSearch(() => {
        setSearch(nextSearch.trim());
        setStatusFilter(nextStatus);
        setRouteFilter(nextRoute);
        setPage(1);
      });
    },
    [pulseSearch],
  );

  useEffect(() => {
    const t = window.setTimeout(() => {
      applyFilters(searchDraft, statusDraft, routeDraft);
    }, 300);
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- only re-filter when draft inputs change
  }, [searchDraft, statusDraft, routeDraft]);

  const openRow = useCallback(
    (row: PatrolDto, mode: 'create' | 'edit' | 'view' | 'copy') => {
      selectActiveRow(row);
      if (mode === 'create') {
        navigate('/td-tk/tao-moi');
        return;
      }
      if (mode === 'copy') {
        navigate(`/td-tk/tao-moi?copyFrom=${encodeURIComponent(row.id)}`);
        return;
      }
      const qs = mode === 'edit' ? '?mode=edit' : '';
      navigate(`/td-tk/${encodeURIComponent(row.id)}${qs}`);
    },
    [selectActiveRow, navigate],
  );

  const openCreate = useCallback(() => {
    if (!perms.canCreate) return;
    navigate('/td-tk/tao-moi');
  }, [perms.canCreate, navigate]);

  const reloadAll = useCallback(() => {
    setLoadingMode('filter');
    load();
  }, [load, setLoadingMode]);

  const handlePageChange = useCallback((next: number) => {
    setPage(next);
  }, []);

  const handlePageSizeChange = useCallback((next: number) => {
    setPageSize(next);
    setPage(1);
  }, []);

  const handleHistoryToolbar = useCallback(() => {
    if (!activeRow) {
      dispatchAppToast(dispatch, {
        message: 'Chọn một dòng (menu dòng) rồi mở Lịch sử.',
        type: 'info',
      });
      return;
    }
    catalogHistory.openHistory({
      documentType: PAGE_ID,
      documentId: activeRow.id,
      documentCode: activeRow.code,
    });
  }, [activeRow, catalogHistory.openHistory, dispatch]);

  const editConfigStub = useCallback(() => {
    setConfigHint(true);
  }, []);

  const deleteRow = useCallback(
    async (row: PatrolDto) => {
      if (!perms.canDelete) {
        window.alert('Không có quyền xóa phiên tuần tra.');
        return;
      }
      if (
        !window.confirm(
          `Xóa phiên tuần «${row.code} — ${row.userName} / ${row.route}»?`,
        )
      ) {
        return;
      }
      try {
        await patrolService.delete(row.id);
        clearSelection();
        setLoadingMode('filter');
        load();
      } catch (err) {
        window.alert(err instanceof Error ? err.message : 'Xóa phiên tuần thất bại.');
      }
    },
    [perms.canDelete, clearSelection, setLoadingMode, load],
  );

  const catalogToolbar = useMemo(
    () => ({
      testIdPrefix: TEST_ID,
      onRefresh: reloadAll,
      canAdd: perms.canCreate,
      onAdd: openCreate,
      canHistory: true,
      onHistory: handleHistoryToolbar,
      showSchemaConfig: true,
      onEditConfig: editConfigStub,
      showEdit: Boolean(activeRow && perms.canUpdate),
      showView: Boolean(activeRow && perms.canRead),
      onEdit: activeRow ? () => openRow(activeRow, 'edit') : undefined,
      onView: activeRow ? () => openRow(activeRow, 'view') : undefined,
      canDelete: Boolean(activeRow && perms.canDelete),
      onDelete: activeRow
        ? () => {
            void deleteRow(activeRow);
          }
        : undefined,
    }),
    [
      reloadAll,
      perms.canCreate,
      perms.canUpdate,
      perms.canRead,
      perms.canDelete,
      openCreate,
      handleHistoryToolbar,
      editConfigStub,
      activeRow,
      openRow,
      deleteRow,
    ],
  );

  const listFilters = useMemo(
    () => (
      <ErpListHeaderFilters testIdPrefix={TEST_ID} filterCols={3}>
        <LinListFilterField testId={`${TEST_ID}-field-search`}>
          <SearchTextInput
            label="Tìm kiếm"
            placeholder="Mã / NV / tuyến / loại / trạng thái…"
            value={searchDraft}
            onChange={setSearchDraft}
            onSearch={() => applyFilters(searchDraft, statusDraft, routeDraft)}
            testId={`${TEST_ID}-search-text`}
          />
        </LinListFilterField>
        <LinListFilterField testId={`${TEST_ID}-field-status`}>
          <SearchInput
            label="Trạng thái"
            config={STATUS_LOOKUP_CONFIG}
            value={statusDraft}
            primaryDisplay={lookupLabel(STATUS_LOOKUP, statusDraft)}
            showSecondaryInput={false}
            placeholder="Tất cả trạng thái"
            onChange={(item) => setStatusDraft(item.value)}
            onClear={() => setStatusDraft('')}
          />
        </LinListFilterField>
        <LinListFilterField testId={`${TEST_ID}-field-route`}>
          <SearchInput
            label="Tuyến"
            config={ROAD_ROUTE_LOOKUP_CONFIG}
            value={routeDraft}
            primaryDisplay={lookupNameOnly(ROAD_ROUTE_SEED, routeDraft)}
            showSecondaryInput={false}
            placeholder="Tất cả tuyến"
            onChange={(item) => setRouteDraft(item.value)}
            onClear={() => setRouteDraft('')}
          />
        </LinListFilterField>
      </ErpListHeaderFilters>
    ),
    [searchDraft, statusDraft, routeDraft, applyFilters],
  );

  const columns = useMemo<LinCatalogDataColumn<PatrolDto>[]>(
    () => [
      {
        key: 'code',
        label: 'Mã phiên',
        width: 140,
        allowSort: true,
        render: (row) => (
          <button
            type="button"
            className={styles.codeLink}
            onClick={() => openRow(row, 'view')}
            data-testid={`${TEST_ID}-code-${row.code}`}
          >
            {row.code}
          </button>
        ),
        getDisplayValue: (r) => r.code,
      },
      {
        key: 'userName',
        label: 'Nhân viên',
        width: 150,
        allowSort: true,
        render: (row) => row.userName,
        getDisplayValue: (r) => r.userName,
      },
      {
        key: 'route',
        label: 'Tuyến',
        width: 90,
        allowSort: true,
        render: (row) => row.route,
        getDisplayValue: (r) => r.route,
      },
      {
        key: 'patrolType',
        label: 'Loại tuần',
        width: 110,
        allowSort: true,
        render: (row) => row.patrolType,
        getDisplayValue: (r) => r.patrolType,
      },
      {
        key: 'plannedDate',
        label: 'Ngày KH',
        width: 110,
        allowSort: true,
        render: (row) => formatDate(row.plannedDate),
        getDisplayValue: (r) => r.plannedDate,
      },
      {
        key: 'checkInCount',
        label: 'Check-in',
        width: 90,
        allowSort: true,
        render: (row) => row.checkInCount,
        getDisplayValue: (r) => String(r.checkInCount),
      },
      {
        key: 'coveragePercent',
        label: 'Coverage %',
        width: 100,
        allowSort: true,
        render: (row) => `${Number(row.coveragePercent).toFixed(1)}%`,
        getDisplayValue: (r) => String(r.coveragePercent),
      },
      {
        key: 'status',
        label: 'Trạng thái',
        width: 120,
        allowSort: true,
        render: (row) => row.status,
        getDisplayValue: (r) => r.status,
      },
      {
        key: 'offlineQueued',
        label: 'Offline',
        width: 90,
        allowSort: true,
        render: (row) => (
          <span className={row.offlineQueued ? styles.offlineBad : styles.offlineOk}>
            {row.offlineQueued ? 'Queue' : 'Online'}
          </span>
        ),
        getDisplayValue: (r) => (r.offlineQueued ? 'Queue' : 'Online'),
      },
    ],
    [openRow],
  );

  const rowMenuItems = useMemo(
    () =>
      buildCatalogRowMenuItems({
        showView: perms.canRead,
        showEdit: perms.canUpdate,
        showCopy: perms.canCreate,
        showDelete: perms.canDelete,
        showHistory: perms.canRead,
      }),
    [perms.canRead, perms.canUpdate, perms.canCreate, perms.canDelete],
  );

  const handleRowMenuSelect = useCallback(
    (action: string) => {
      const row = rowMenu?.row;
      setRowMenu(null);
      if (!row) return;
      switch (action) {
        case 'view':
          openRow(row, 'view');
          break;
        case 'edit':
          openRow(row, 'edit');
          break;
        case 'copy':
          openRow(row, 'copy');
          break;
        case 'delete':
          void deleteRow(row);
          break;
        case 'history':
          catalogHistory.openHistory({
            documentType: PAGE_ID,
            documentId: row.id,
            documentCode: row.code,
          });
          break;
        default:
          break;
      }
    },
    [rowMenu?.row, openRow, deleteRow, catalogHistory.openHistory],
  );

  const emptyMessage =
    search.trim() || statusFilter || routeFilter
      ? 'Không có phiên tuần tra phù hợp bộ lọc.'
      : 'Không có dữ liệu phiên tuần tra.';

  const tableConfig = useMemo(
    () => ({
      ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
      resizable: true,
    }),
    [],
  );

  return (
    <div
      className={styles.page}
      data-catalog-list-page
      data-testid={`${TEST_ID}-page`}
    >
      <LinPageLayout
        kind="catalog"
        filterBarLayout="standard"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        header={{
          title: 'Tuần đường / tuần kiểm',
          titleIconClass: 'fas fa-route',
          pageId: PAGE_ID,
        }}
        toolbar={fromCatalogToolbar(catalogToolbar)}
        listTitle="Sổ phiên tuần tra / check-in"
        listRowMenuHelp
        filters={listFilters}
        filtersTestId={`${TEST_ID}-filters`}
        showTableLoading={showTableLoading}
        pageLoading={pageLoading}
        skeletonRows={8}
        footer={
          <LinCatalogListPagination
            testIdPrefix={TEST_ID}
            page={page}
            pageSize={pageSize}
            totalCount={totalCount}
            onPageChange={handlePageChange}
            onPageSizeChange={handlePageSizeChange}
          />
        }
        modals={
          <>
            <LinCatalogRowActionMenu
              open={rowMenu != null}
              x={rowMenu?.x ?? 0}
              y={rowMenu?.y ?? 0}
              testIdPrefix={TEST_ID}
              onClose={() => setRowMenu(null)}
              onSelect={(action) => {
                handleRowMenuSelect(action);
              }}
              items={rowMenuItems}
            />
            {catalogHistory.modalProps ? (
              <LinCatalogHistoryModal
                {...catalogHistory.modalProps}
                testIdPrefix={TEST_ID}
                onError={(message) =>
                  dispatchAppToast(dispatch, { message, type: 'error' })
                }
              />
            ) : null}
          </>
        }
      >
        <div className={styles.gridWrap} data-testid={`${TEST_ID}-grid-wrap`}>
          <LinCatalogDataGrid
            testIdPrefix={TEST_ID}
            rows={items}
            page={page}
            pageSize={pageSize}
            columns={columns}
            getRowId={(r) => r.id}
            selection={listSelection}
            tableConfig={tableConfig}
            paginateClient={false}
            empty={
              <div className={styles.empty} data-testid={`${TEST_ID}-empty`}>
                {emptyMessage}
              </div>
            }
            onRowOpenActionMenu={({ row, x, y }) => {
              selectActiveRow(row);
              setRowMenu({ row, x, y });
            }}
            onRowDoubleClick={(row) => openRow(row, 'view')}
            rowMenuHintDismissStorageKey={ROW_MENU_HINT_KEY}
          />
        </div>
      </LinPageLayout>
      {configHint ? (
        <div className={styles.configHint} role="dialog" aria-modal="true">
          <div className={styles.configHintCard}>
            <p>
              Cấu hình cột lưới dùng mặc định Kind B (kéo/đổi độ rộng cột ON).
              Schema editor đầy đủ gắn catalog-ui-schema khi IAM sẵn sàng.
            </p>
            <Button type="button" onClick={() => setConfigHint(false)}>
              Đóng
            </Button>
          </div>
        </div>
      ) : null}
    </div>
  );
};

export default PatrolListPage;
